                "name": "GetProductVersionInfo",
                "version": "1.7.3",
                "description": "Retrieves the version information of the running Archicad: build number, language code, product family and version text, plus the product name, product type, main/update/hotfix versions, the available domains (Architecture, MEP) and the CEIP project identifier of the open project from Archicad 29. Requires Archicad 28 or later.",
                "inputScheme": null,
                "outputScheme": {
        "type": "object",
        "properties": {
            "productName": {
                "type": "string",
                "description": "The name of the product. Archicad 29 or later."
            },
            "productType": {
                "type": "string",
                "description": "The Graphisoft product type. Archicad 29 or later."
            },
            "productFamilyId": {
                "type": "string",
                "description": "The identifier of the product family."
            },
            "languageCode": {
                "type": "string",
                "description": "The Graphisoft language code of the running Archicad (for example INT, GER)."
            },
            "buildNumber": {
                "type": "integer",
                "description": "The build number of the running Archicad."
            },
            "versionString": {
                "type": "string",
                "description": "The full version of the running Archicad as text."
            },
            "mainVersion": {
                "type": "string",
                "description": "The main version, as text. Archicad 29 or later."
            },
            "updateVersion": {
                "type": "string",
                "description": "The update version, as text. Archicad 29 or later."
            },
            "hotfixVersion": {
                "type": "string",
                "description": "The hotfix version, as text. Archicad 29 or later."
            },
            "versionNumbers": {
                "type": "array",
                "items": {
                    "type": "integer"
                },
                "description": "The three parts of the version number. Archicad 28 only."
            },
            "availableDomains": {
                "type": "array",
                "items": {
                    "$ref": "#/ProductDomain"
                },
                "description": "The domains available in the running Archicad. Archicad 29 or later."
            },
            "ceipProjectId": {
                "type": "string",
                "description": "The CEIP project identifier of the open project. Left out when no saved project is open. Archicad 29 or later."
            }
        },
        "additionalProperties": false,
        "required": [
            "productFamilyId",
            "languageCode",
            "buildNumber",
            "versionString"
        ]
    }
